mockup.css:
.mock-section-stat-band { background: #ece7db; color: #1b1811; font-family: var(--f-sans);
  display: grid; grid-template-columns: repeat(4, 1fr); align-items: center; padding: 0 5cqw; }
.mock-section-stat-band .fig { padding: 0 2.6cqw; border-left: 1px solid rgba(27,24,17,.2);
  display: flex; flex-direction: column; gap: .9cqw; }
.mock-section-stat-band .fig:first-child { border-left: 0; padding-left: 0; }
.mock-section-stat-band .fig b { font-family: var(--f-serif); font-weight: 400; font-size: 8.2cqw;
  line-height: .88; letter-spacing: -.035em; color: #9d3311; }
.mock-section-stat-band .fig span { font-size: 1.25cqw; letter-spacing: .14em; text-transform: uppercase; opacity: .55; }
.mock-section-stat-band .fig i { font-style: normal; font-size: 1.4cqw; line-height: 1.45; opacity: .78; }
